29	// Backend contract confirmed live on PRE (LESSONS.md: "The profile events
30	// endpoint takes period=active|past, not status=upcoming|past"): `period` is
31	// required on this endpoint too, or the backend returns HTTP 500
32	// "Required request parameter 'period' ... is not present". There's no
33	// "all periods" value, and MAX_FAVORITES-sized single-page callers (route.ts,
34	// preferits/page.tsx) need both active and past items in one merged list —
35	// the page renders active events and separately prunes expired ones — so
36	// fetch both periods and merge rather than picking one.
37	async function fetchFavoritesPeriod(
38	  base: string,
39	  accessToken: string,
40	  period: "active" | "past",
41	  page: number,
42	  size: number
43	): Promise<FavoriteEventsPageDTO | null> {
44	  try {
45	    const query = new URLSearchParams({
46	      page: String(page),
47	      size: String(size),
48	      period,
49	    }).toString();
50	    const response = await fetchWithHmac(`${base}?${query}`, {
51	      headers: authHeaders(accessToken),
52	    });
53	    if (!response.ok) {
54	      await logBackendError(`listFavoriteEventsExternal(period=${period})`, response);
55	      return null;
56	    }
57	    return parseFavoriteEventsPage(await response.json());
58	  } catch (error) {
59	    console.error(`listFavoriteEventsExternal(period=${period}): failed`, error);
60	    return null;
61	  }
62	}
63	
64	// `page`/`size` are applied identically to both period calls, then
65	// concatenated — correct for the "one page holds everything" callers this
66	// has today (page=0, size=MAX_FAVORITES). A caller requesting page > 0
67	// would NOT get a coherent "page N of the combined list", since active and
68	// past are paginated independently before merging.
69	export async function listFavoriteEventsExternal(
70	  accessToken: string,
71	  page = 0,
72	  size = 50
73	): Promise<FavoriteEventsPageDTO | null> {
74	  const base = favoritesBaseUrl();
75	  if (!base) return null;
76	
77	  const [activePage, pastPage] = await Promise.all([
78	    fetchFavoritesPeriod(base, accessToken, "active", page, size),
79	    fetchFavoritesPeriod(base, accessToken, "past", page, size),
80	  ]);
81	  // Either leg failing means the list is incomplete — surface unavailable
82	  // rather than a partial list that looks complete.
83	  if (activePage === null || pastPage === null) return null;
84	
85	  const content = [...activePage.content, ...pastPage.content];
86	  const totalElements = activePage.totalElements + pastPage.totalElements;
87	  // Up to `size` items come back from each leg, so content.length can reach
88	  // 2*size — pageSize must reflect that bound, not the single-leg `size`,
89	  // or a caller trusting content.length <= pageSize gets burned.
90	  const pageSize = size * 2;
91	
92	  return {
93	    content,
94	    currentPage: page,
95	    pageSize,
96	    totalElements,
97	    totalPages: pageSize > 0 ? Math.ceil(totalElements / pageSize) : 0,
98	    last: activePage.last && pastPage.last,
99	  };
100	}
